INSERT INTO houseplants (common_name, scientific_name, description, water_frequency_days, water_tip, sunlight, environment, seasonal_adjustment) VALUES
-- Batch 1: 1-50
('African Mask Plant', 'Alocasia amazonica', 'Striking arrow-shaped leaves with bold white veining. Dramatic tropical foliage plant that goes dormant in winter.', 5, 'Keep soil consistently moist but not soggy.', 'Bright indirect light', '65-80°F, high humidity, rich well-draining mix', '{"winter_multiplier": 2.0}'),
('African Violet', 'Saintpaulia ionantha', 'Compact flowering plant with velvety leaves and colorful blooms. Flowers almost year-round in the right conditions.', 7, 'Water from below to avoid crown rot.', 'Bright indirect light, no direct sun', '65-80°F, moderate humidity, light porous soil', '{"winter_multiplier": 1.3}'),
('Agave', 'Agave americana', 'Sculptural rosette succulent with thick fleshy leaves. Extremely drought-tolerant and slow-growing.', 21, 'Soak thoroughly, then let dry completely.', 'Full sun to bright direct light', '60-90°F, low humidity, sandy cactus mix', '{"winter_multiplier": 1.3}'),
('Air Plant', 'Tillandsia ionantha', 'Rootless epiphyte that absorbs water and nutrients through its leaves. Needs no soil and works in creative displays.', 4, 'Mist daily or soak 20 min weekly.', 'Bright indirect light', '50-90°F, moderate humidity, no soil needed', '{"winter_multiplier": 1.5}'),
('Aloe Vera', 'Aloe barbadensis miller', 'Medicinal succulent with thick gel-filled leaves. Easy to grow and useful for minor burns and skin care.', 14, 'Let soil dry completely between waterings.', 'Bright direct to indirect light', '55-80°F, low humidity, sandy well-draining mix', '{"winter_multiplier": 1.5}'),
('Aluminum Plant', 'Pilea cadierei', 'Low-growing foliage plant with silver-splashed green leaves. Fast-growing and easy to propagate from cuttings.', 5, 'Keep soil evenly moist, not waterlogged.', 'Bright indirect light', '60-75°F, moderate humidity, standard potting mix', '{"winter_multiplier": 1.5}'),
('Angel Wing Begonia', 'Begonia coccinea', 'Cane-type begonia with wing-shaped spotted leaves and dangling flower clusters. Grows upright and can reach several feet tall.', 5, 'Water when top inch of soil is dry.', 'Bright indirect light', '65-75°F, moderate to high humidity, rich well-draining mix', '{"winter_multiplier": 1.5}'),
('Anthurium', 'Anthurium andraeanum', 'Glossy heart-shaped spathes in red, pink, or white above dark foliage. Long-lasting blooms make it a popular gift plant.', 7, 'Water when top inch dries; mist leaves.', 'Bright indirect light', '65-80°F, high humidity, orchid-type chunky mix', '{"winter_multiplier": 1.5}'),
('Areca Palm', 'Dypsis lutescens', 'Feathery golden-stemmed palm that acts as a natural humidifier. One of the best air-purifying houseplants.', 7, 'Keep soil lightly moist; avoid standing water.', 'Bright indirect light', '65-75°F, moderate to high humidity, peat-based mix', '{"winter_multiplier": 1.5}'),
('Arrowhead Plant', 'Syngonium podophyllum', 'Arrow-shaped leaves that become lobed with age. Versatile grower that can climb or trail depending on support.', 7, 'Water when top inch of soil dries out.', 'Medium to bright indirect light', '60-80°F, moderate humidity, standard potting mix', '{"winter_multiplier": 1.5}'),
('Asparagus Fern', 'Asparagus setaceus', 'Feathery, lace-like foliage on arching stems. Not a true fern but an asparagus relative that drops needle-like leaves if stressed.', 5, 'Keep soil evenly moist; mist regularly.', 'Bright indirect light', '60-75°F, moderate to high humidity, rich potting mix', '{"winter_multiplier": 1.5}'),
('Baby Rubber Plant', 'Peperomia obtusifolia', 'Compact plant with thick glossy rounded leaves. Low-maintenance and tolerant of lower light conditions.', 10, 'Let top half of soil dry between waterings.', 'Medium to bright indirect light', '65-75°F, moderate humidity, well-draining mix', '{"winter_multiplier": 1.5}'),
('Baby''s Tears', 'Soleirolia soleirolii', 'Tiny round leaves form a dense creeping mat. Excellent ground cover for terrariums and humid environments.', 3, 'Keep soil consistently moist; never let dry.', 'Medium indirect light', '60-70°F, high humidity, rich moisture-retaining mix', '{"winter_multiplier": 1.3}'),
('Bamboo Palm', 'Chamaedorea seifrizii', 'Clumping palm with slender bamboo-like stems and feathery fronds. Great air purifier tolerant of lower light.', 7, 'Keep soil lightly moist; reduce in winter.', 'Medium to bright indirect light', '65-80°F, moderate humidity, peat-based mix', '{"winter_multiplier": 1.5}'),
('Banana Plant', 'Musa acuminata', 'Large tropical leaves that unfurl dramatically from a central stalk. Fast grower that brings bold jungle vibes indoors.', 5, 'Keep soil consistently moist; loves humidity.', 'Bright direct to indirect light', '65-85°F, high humidity, rich well-draining mix', '{"winter_multiplier": 1.8}'),
('Bear''s Paw', 'Cotyledon tomentosa', 'Fuzzy succulent with chubby leaves tipped with small teeth resembling claws. Slow-growing and charming on a sunny sill.', 14, 'Soak and dry; very rot-prone if overwatered.', 'Bright direct light', '60-80°F, low humidity, gritty cactus mix', '{"winter_multiplier": 1.3}'),
('Bird of Paradise', 'Strelitzia reginae', 'Bold banana-like leaves that fan out from a central clump. Rarely blooms indoors but prized for its dramatic foliage.', 7, 'Water when top inch dries; likes moisture.', 'Bright direct to indirect light', '65-80°F, moderate humidity, rich well-draining mix', '{"winter_multiplier": 1.5}'),
('Bird''s Nest Fern', 'Asplenium nidus', 'Rosette of wavy bright-green fronds emerging from a central nest. Epiphytic fern that thrives in humid bathrooms.', 7, 'Keep soil moist; water around the edge, not the center.', 'Medium indirect light', '60-80°F, high humidity, peat and perlite mix', '{"winter_multiplier": 1.5}'),
('Black Rose Aeonium', 'Aeonium arboreum Zwartkop', 'Dramatic succulent rosettes in deep burgundy-black on branching stems. Goes dormant in summer heat.', 14, 'Water when soil is fully dry; reduce in summer.', 'Full sun to bright light', '40-75°F, low humidity, gritty well-draining mix', '{"winter_multiplier": 1.2}'),
('Blue Star Fern', 'Phlebodium aureum', 'Blue-green fronds with a soft powdery look on fuzzy rhizomes. More drought-tolerant than most ferns.', 7, 'Water when top inch dries; tolerates some neglect.', 'Medium indirect light', '60-80°F, moderate humidity, well-draining peat mix', '{"winter_multiplier": 1.5}'),
('Boston Fern', 'Nephrolepis exaltata', 'Lush cascading fronds make this the classic hanging fern. Excellent air purifier but demands consistent moisture.', 3, 'Keep soil moist at all times; mist daily.', 'Bright indirect light, no direct sun', '60-75°F, high humidity, peat-based mix', '{"winter_multiplier": 1.5}'),
('Bougainvillea', 'Bougainvillea spectabilis', 'Vigorous tropical vine with papery bracts in vivid pinks, purples, and oranges. Needs lots of sun to flower indoors.', 7, 'Let soil dry between waterings; drought triggers blooms.', 'Full direct sun', '60-85°F, low to moderate humidity, well-draining mix', '{"winter_multiplier": 1.5}'),
('Bromeliad', 'Guzmania lingulata', 'Rosette of strappy leaves with a showy central flower spike. Water collects in the central cup naturally.', 7, 'Keep central cup filled; flush weekly to prevent rot.', 'Bright indirect light', '65-80°F, moderate to high humidity, orchid bark mix', '{"winter_multiplier": 1.5}'),
('Bunny Ear Cactus', 'Opuntia microdasys', 'Flat pad cactus dotted with clusters of tiny glochids instead of large spines. Slow-growing and sculptural.', 21, 'Soak thoroughly, then let dry completely.', 'Full direct sun', '50-85°F, low humidity, sandy cactus mix', '{"winter_multiplier": 1.3}'),
('Burro''s Tail', 'Sedum morganianum', 'Trailing succulent with plump overlapping leaves on rope-like stems. Fragile leaves detach easily but root on contact.', 14, 'Let soil dry fully; water deeply but infrequently.', 'Bright direct to indirect light', '55-80°F, low humidity, gritty well-draining mix', '{"winter_multiplier": 1.3}'),
('Caladium', 'Caladium bicolor', 'Showy heart-shaped leaves in vivid pinks, reds, and whites. Tuberous plant that dies back and goes dormant annually.', 5, 'Keep soil evenly moist during growing season.', 'Bright indirect light; tolerates some shade', '70-85°F, high humidity, rich peat mix', '{"winter_multiplier": 2.0}'),
('Calathea', 'Calathea orbifolia', 'Large round leaves with silver-green striping that fold up at night. A prayer plant relative that demands humidity.', 5, 'Keep soil moist with filtered or distilled water.', 'Medium indirect light', '65-80°F, high humidity, peat and perlite mix', '{"winter_multiplier": 1.5}'),
('Cape Primrose', 'Streptocarpus spp.', 'Rosette of textured leaves producing trumpet-shaped flowers on slender stalks. Related to African violets with similar care.', 7, 'Water from below; let top dry slightly.', 'Bright indirect light', '60-75°F, moderate humidity, light well-draining mix', '{"winter_multiplier": 1.3}'),
('Cast Iron Plant', 'Aspidistra elatior', 'Nearly indestructible foliage plant with broad dark-green leaves. Tolerates neglect, low light, and temperature swings.', 10, 'Water when top few inches are dry; very forgiving.', 'Low to medium indirect light', '45-85°F, any humidity, standard potting mix', '{"winter_multiplier": 1.5}'),
('Cathedral Cactus', 'Euphorbia trigona', 'Tall columnar succulent with ridged triangular stems and small leaves. Fast grower often mistaken for a true cactus.', 14, 'Let soil dry between waterings; reduce in winter.', 'Bright direct to indirect light', '60-80°F, low humidity, cactus mix', '{"winter_multiplier": 1.5}'),
('Chinese Evergreen', 'Aglaonema commutatum', 'Patterned lance-shaped leaves in silver, green, pink, or red. One of the most tolerant houseplants for low-light spaces.', 7, 'Water when top inch dries; tolerates some neglect.', 'Low to medium indirect light', '65-80°F, moderate humidity, standard potting mix', '{"winter_multiplier": 1.5}'),
('Chinese Fan Palm', 'Livistona chinensis', 'Graceful palm with large fan-shaped fronds on slender trunks. Slow-growing indoors but makes an elegant statement.', 7, 'Keep soil lightly moist; don''t let it sit in water.', 'Bright indirect light', '60-80°F, moderate humidity, well-draining palm mix', '{"winter_multiplier": 1.5}'),
('Chinese Money Plant', 'Pilea peperomioides', 'Round pancake-shaped leaves on thin petioles from a central stem. Produces abundant offsets to share with friends.', 7, 'Let top inch dry between waterings; rotate for even growth.', 'Bright indirect light', '60-75°F, moderate humidity, well-draining mix', '{"winter_multiplier": 1.5}'),
('Christmas Cactus', 'Schlumbergera bridgesii', 'Segmented trailing stems that burst into colorful blooms around the holidays. Needs short days and cool temps to trigger flowering.', 7, 'Keep lightly moist; reduce water to trigger blooms.', 'Bright indirect light', '60-70°F, moderate humidity, well-draining epiphyte mix', '{"winter_multiplier": 1.3}'),
('Clivia', 'Clivia miniata', 'Strap-leaved evergreen that produces clusters of orange trumpet flowers. Needs a cool winter rest to bloom reliably.', 7, 'Moderate water in growth; keep nearly dry in winter rest.', 'Bright indirect light; no direct sun', '50-75°F, moderate humidity, rich well-draining mix', '{"winter_multiplier": 2.0}'),
('Coffee Plant', 'Coffea arabica', 'Glossy dark-green leaves on an upright shrub that can produce small fragrant flowers. Occasionally bears small coffee cherries indoors.', 5, 'Keep soil consistently moist but never soggy.', 'Bright indirect light', '65-80°F, high humidity, rich acidic well-draining mix', '{"winter_multiplier": 1.5}'),
('Coleus', 'Plectranthus scutellarioides', 'Vibrant multicolored foliage in endless pattern and color combinations. Fast-growing and easy to propagate from cuttings.', 3, 'Keep soil evenly moist; wilts quickly when dry.', 'Bright indirect to partial direct light', '60-75°F, moderate humidity, rich potting mix', '{"winter_multiplier": 1.5}'),
('Coral Cactus', 'Euphorbia lactea cristata', 'Fan-shaped crested growth often grafted onto a straight euphorbia stem. Unusual sculptural succulent that''s a conversation piece.', 14, 'Water sparingly; let soil dry fully between waterings.', 'Bright indirect light', '60-80°F, low humidity, gritty cactus mix', '{"winter_multiplier": 1.5}'),
('Corn Plant', 'Dracaena fragrans', 'Woody-stemmed plant with broad arching leaves striped in green and yellow. One of the easiest tall houseplants to maintain.', 7, 'Water when top inch dries; sensitive to fluoride in tap water.', 'Medium to bright indirect light', '60-75°F, moderate humidity, standard potting mix', '{"winter_multiplier": 1.5}'),
('Creeping Fig', 'Ficus pumila', 'Tiny heart-shaped leaves on wiry stems that cling to surfaces. Vigorous creeping vine ideal for topiaries and terrariums.', 5, 'Keep soil consistently moist; mist frequently.', 'Bright indirect light', '60-80°F, high humidity, well-draining mix', '{"winter_multiplier": 1.5}'),
